import re, os
SITE = "/home/claude/proj/site/articles"

def sl(id, name, mn, mx, step, val, u="", d=0):
    return f'<label class="ia-sl">{name}<output></output><input type="range" id="{id}" min="{mn}" max="{mx}" step="{step}" value="{val}"' + (f' data-u="{u}"' if u else "") + (f' data-d="{d}"' if d else "") + "></label>"

def outs(items):
    return '<div class="ia-outs">' + "".join(f'<div class="ia-o{" key" if k else ""}"><span>{n}</span><b id="{i}">—</b><small>{u}</small></div>' for i, n, u, k in items) + "</div>"

WIDE = {"ia-ecd", "ia-clean", "ia-kick", "ia-stuck", "ia-vib", "ia-mwd", "ia-bha"}
def sec(id, eyebrow, title, desc, canvas, side, after="", label=""):
    return (f'<section class="wx ia{" wide" if id in WIDE else ""}" id="{id}" aria-label="{label or title}"><div class="wx-top"><div class="eyebrow">{eyebrow}</div><b>{title}</b><p>{desc}</p></div>'
            f'<div class="ia-grid">{canvas}<div class="ia-side">{side}</div></div>{after}</section>\n')

CV = lambda h=420, cls="ia-cv flat", extra="": f'<canvas class="{cls}" style="height:{h}px"{extra} role="img" aria-label="Интерактивная модель"></canvas>'

