for slug, (id, html) in M.items():
    p = os.path.join(SITE, slug, "index.html")
    s = open(p, encoding="utf-8").read()
    s = re.sub(r'<section class="wx ia[^"]*" id="' + id + r'".*?</section>\n', "", s, flags=re.S)
    i = s.index("<h2", s.index('class="article"'))
    s = s[:i] + html + s[i:]
    js = "@art-viz1.js" if id in ("ia-ecd", "ia-clean", "ia-kick", "ia-stuck", "ia-vib") else "@art-viz2.js"
    if js not in s:
        add = ("" if "82ef5376c6.js" in s else '<script src="../../assets/j/82ef5376c6.js" data-ia="dh3d"></script>\n') + f'<script src="../../assets/j/{js}"></script>\n'
        s = s.replace("</main>", add + "</main>", 1)
    open(p, "w", encoding="utf-8").write(s)

# weight-transfer: та же модель передачи нагрузки, что в статье wob-loss
p = os.path.join(SITE, "weight-transfer", "index.html")
s = open(p, encoding="utf-8").read()
w = open(os.path.join(SITE, "wob-loss", "index.html"), encoding="utf-8").read()
blk = re.search(r'<section class="wx ia" id="ia-wob".*?</section>', w, re.S).group(0)
s = re.sub(r'<section class="wx ia" id="ia-wob".*?</section>\n', "", s, flags=re.S)
i = s.index("<h2", s.index('class="article"'))
s = s[:i] + blk + '\n<p>Практика (признаки, причины и приёмы в слайде) разобрана в статье <a href="../../articles/wob-loss/">Нагрузка не доходит до долота</a>.</p>\n' + s[i:]
if "@wob-loss.js" not in s:
    s = s.replace("</main>", ('' if "82ef5376c6.js" in s else '<script src="../../assets/j/82ef5376c6.js" data-ia="dh3d"></script>\n') + '<script src="../../assets/j/@wob-loss.js"></script>\n</main>', 1)
if "@articles.css" not in s:
    s = s.replace("</head>", '<link rel="stylesheet" href="../../assets/c/@articles.css"></head>', 1)
open(p, "w", encoding="utf-8").write(s)
print("ok")
